The lower median is 4: sorting gives [1, 2, 4, 4, 7, 9], and the selected zero-based index is (6 − 1) / 2 = 2. The function copies the caller’s array and applies std::nth_element to that copy, so the original array remains unchanged; empty input throws std::invalid_argument.

For correctness, let the size be n > 0 and define k = floor((n − 1) / 2). If n = 2m + 1, then k = m, the unique middle index; if n = 2m, then k = m − 1, the lower of the two middle indices. std::nth_element places at index k the value that would occupy that index in sorted order, including when values are duplicated, so returning that value gives the lower median.

Compile as C++17 and run with assertions enabled, without defining NDEBUG.

```cpp
#include <algorithm>
#include <cassert>
#include <cstddef>
#include <iostream>
#include <stdexcept>
#include <vector>

int lower_median(const std::vector<int>& values) {
    if (values.empty()) {
        throw std::invalid_argument("lower_median requires nonempty input");
    }

    std::vector<int> copy = values;
    const std::size_t k = (copy.size() - 1) / 2;
    auto middle = copy.begin() +
        static_cast<std::vector<int>::difference_type>(k);
    std::nth_element(copy.begin(), middle, copy.end());
    return *middle;
}

int main() {
    // Requested example: even size and duplicate values.
    const std::vector<int> example{9, 1, 4, 4, 7, 2};
    const auto original = example;
    const int result = lower_median(example);
    assert(result == 4);
    assert(example == original);

    // Duplicates.
    const std::vector<int> duplicates{5, 2, 2, 2, 9};
    assert(lower_median(duplicates) == 2);

    // Odd size: sorted order is [1, 3, 5, 7, 9].
    const std::vector<int> odd{9, 3, 7, 1, 5};
    assert(lower_median(odd) == 5);

    // Even size: lower middle is 3, not 7 or their average.
    const std::vector<int> even{9, 1, 7, 3};
    assert(lower_median(even) == 3);

    // Singleton.
    const std::vector<int> singleton{42};
    assert(lower_median(singleton) == 42);

    // Empty input must be rejected.
    bool rejected = false;
    try {
        (void)lower_median(std::vector<int>{});
    } catch (const std::invalid_argument&) {
        rejected = true;
    }
    assert(rejected);

    std::cout << "Lower median: " << result << '\n';
    std::cout << "All tests passed.\n";
}
```
